-- TRAIN WITH PANDA 0.9.15 · five cardio plan templates as coach records (kind 'programs', plan_type 'cardio').
-- Written 2026-09-28 by Train With Panda. The 0.9.15 web build carries these as window.PANDA_CARDIO_TEMPLATES,
-- but migrate() only seeds the plan library in demo mode, so online coaches saw an empty "Cardio plans" page.
-- Data is byte-for-byte the frontend's template JSON (panda_cardio_walking_start, panda_cardio_bike_base, panda_cardio_treadmill_steady, panda_cardio_rowing_steady, panda_cardio_bike_intervals).
-- Additive: on conflict do nothing, existing records are never rewritten. Validated on insert by panda_cardio_update (0016).
begin;
insert into public.panda_records(kind,id,data) select 'programs', value->>'id', value from jsonb_array_elements($panda0915$[{"id":"panda_cardio_walking_start","name":"01 · Walking Foundations","name_ar":"٠١ · أساسيات المشي","description":"Build a repeatable walking habit, five days each week.","description_ar":"ابنِ عادة مشي منتظمة خمسة أيام في الأسبوع.","notes":"Coach template: review suitability and adjust the targets before assignment. Week 1: 20 min. If comfortable, add 5 min in week 2; hold in week 3; reach 30 min in week 4 only after coach review. Speak comfortably. Step target is optional; do not turn a low-step baseline into an abrupt 8,000-step target.","notes_ar":"نموذج للمدرب: راجع الملاءمة وعدّل الأهداف قبل التخصيص. الأسبوع الأول ٢٠ دقيقة. إذا كان مريحاً أضف ٥ دقائق في الأسبوع الثاني واثبت في الثالث. ارفع إلى ٣٠ دقيقة في الرابع بعد مراجعة المدرب. تكلم براحة؛ هدف الخطوات اختياري.","plan_type":"cardio","weeks":4,"status":"published","version":1,"versions":[],"origin":"Panda Cardio HQ template · 0.9.15","sessions":[{"name":"01 · Walking Foundations","name_ar":"٠١ · أساسيات المشي","day":"Mon Tue Thu Fri Sun","focus":"Build a repeatable walking habit, five days each week.","focus_ar":"ابنِ عادة مشي منتظمة خمسة أيام في الأسبوع.","warmup":[{"exercise_id":"lib_warm_01","prescription":"5 min easy","notes":"Use the main-session activity at an easy pace."}],"exercises":[{"exercise_id":"sheet_19f7c9e8b465","sets":1,"reps":"As prescribed","rest":0,"load":"","notes":"Week 1: 20 min. If comfortable, add 5 min in week 2; hold in week 3; reach 30 min in week 4 only after coach review. Speak comfortably. Step target is optional; do not turn a low-step baseline into an abrupt 8,000-step target.","client_note_ar":"الأسبوع الأول ٢٠ دقيقة. إذا كان مريحاً أضف ٥ دقائق في الأسبوع الثاني واثبت في الثالث. ارفع إلى ٣٠ دقيقة في الرابع بعد مراجعة المدرب. تكلم براحة؛ هدف الخطوات اختياري.","intervals":"Continuous steady movement","cardio":{"method":"walking","intensity":"daily_activity","duration":"20 min","frequency_per_week":5,"speed":"Comfortable walking pace","incline_resistance":"Flat, even route","distance_target":"","step_target":"","recovery":"Rest or easy activity on the other days"}}],"cooldown":[{"exercise_id":"lib_cool_01","prescription":"5 min easy","notes":"Reduce pace gradually; follow the coach’s assigned recovery."}]}]},{"id":"panda_cardio_bike_base","name":"02 · Easy Bike Base","name_ar":"٠٢ · قاعدة الدراجة الهادئة","description":"A low-impact steady ride on three non-consecutive days.","description_ar":"ركوب ثابت قليل الصدمات في ثلاثة أيام غير متتالية.","notes":"Coach template: review suitability and adjust the targets before assignment. Keep full sentences comfortable. Start at 15–20 min if 25 min is not yet comfortable; increase duration before resistance. Main ride 25 min plus 5 min easy warm-up and 5 min cool-down.","notes_ar":"نموذج للمدرب: راجع الملاءمة وعدّل الأهداف قبل التخصيص. حافظ على القدرة على الكلام بجمل كاملة. ابدأ بـ١٥–٢٠ دقيقة إن لزم وزد المدة قبل المقاومة. ٢٥ دقيقة أساسية مع ٥ دقائق للإحماء و٥ للتهدئة.","plan_type":"cardio","weeks":4,"status":"published","version":1,"versions":[],"origin":"Panda Cardio HQ template · 0.9.15","sessions":[{"name":"02 · Easy Bike Base","name_ar":"٠٢ · قاعدة الدراجة الهادئة","day":"Mon / Wed / Fri","focus":"A low-impact steady ride on three non-consecutive days.","focus_ar":"ركوب ثابت قليل الصدمات في ثلاثة أيام غير متتالية.","warmup":[{"exercise_id":"lib_warm_01","prescription":"5 min easy","notes":"Use the main-session activity at an easy pace."}],"exercises":[{"exercise_id":"ex_9058639cc046","sets":1,"reps":"As prescribed","rest":0,"load":"","notes":"Keep full sentences comfortable. Start at 15–20 min if 25 min is not yet comfortable; increase duration before resistance. Main ride 25 min plus 5 min easy warm-up and 5 min cool-down.","client_note_ar":"حافظ على القدرة على الكلام بجمل كاملة. ابدأ بـ١٥–٢٠ دقيقة إن لزم وزد المدة قبل المقاومة. ٢٥ دقيقة أساسية مع ٥ دقائق للإحماء و٥ للتهد